def main():
    ids=['offline-install','offline-download','offline-test','offline-usb']
    for lang,t in TEXT.items():
        path=ROOT/f'manual-{lang}.json';data=json.loads(path.read_text(encoding='utf-8'))
        data['sections']=[s for s in data['sections'] if s.get('id') not in ids]
        data['date']=t['date']
        if t['intro'] not in data['intro']:data['intro']+=' '+t['intro']
        for id,(title,paras) in zip(ids,t['sections']):
            data['sections'].append({'id':id,'title':title,'topic':'settings','paras':paras,'url':URL,'link_label':t['link']})
        path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('Updated four offline sections in each of five manual sources.')
if __name__=='__main__':main()
